import hashlib, os, json
base = "dosyalar"
groups = {}
for root, dirs, files in os.walk(base):
    for f in sorted(files):
        p = os.path.join(root, f)
        h = hashlib.sha256(open(p,'rb').read()).hexdigest()
        rel = os.path.relpath(p, base).replace(os.sep, '/')
        groups.setdefault(h, []).append(rel)

lines = []
for h, paths in groups.items():
    if len(paths) >= 2:
        lines.append(" | ".join(sorted(paths)))
lines.sort(key=lambda s: s.split(' | ')[0])
print(json.dumps({"count": len(lines), "groups": {p[0]: p for p in []}, "sample": lines[:10]}, indent=2))

import hashlib, os
base = "dosyalar"
groups = {}
for root, dirs, files in os.walk(base):
    for f in sorted(files):
        if os.path.join(root, f) == os.path.join(base, "kopyalar.txt"): continue
        p = os.path.join(root, f)
        h = hashlib.sha256(open(p,'rb').read()).hexdigest()
        rel = os.path.relpath(p, base).replace(os.sep, '/')
        groups.setdefault(h, []).append(rel)

expected = []
for paths in groups.values():
    if len(paths) >= 2:
        expected.append(" | ".join(sorted(paths)))
expected.sort(key=lambda s: s.split(' | ')[0])

actual = [l.rstrip('\n') for l in open('kopyalar.txt', encoding='utf-8') if l.strip()]
print(expected == actual, len(expected), len(actual))
for a,b in zip(expected, actual): print(repr(a)==repr(b), repr(a), repr(b))

